import{_ as t,o as i,c as r,a2 as p}from"./chunks/framework.CHeM0PsO.js";const s="/images/third-party-icons.webp",o="/images/third-party-aria-appstore.webp",e="/images/third-party-miria-appstore.webp",n="/images/third-party-group-files.webp",c="/images/third-party-group-downloads.webp",m="/images/aria-settings.webp",l="/images/aria-account.webp",g="/images/aria-add-account.webp",_="/images/aria-server-url.webp",h="/images/aria-select-account.webp",d="/images/aria-auth-request.webp",u="/images/aria-allow.webp",b="/images/aria-allowed.webp",k="/images/aria-authenticated.webp",f="/images/token-entry.webp",w="/images/token-permissions.webp",y="/images/token-created.webp",A="/images/token-notification.webp",q="/images/token-login.webp",S="/images/token-form.webp",$=JSON.parse('{"title":"第三方应用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/third-party.md","filePath":"guide/third-party.md","lastUpdated":1789295632000}'),P={name:"guide/third-party.md"};function v(x,a,N,M,T,G){return i(),r("div",null,[...a[0]||(a[0]=[p('<h1 id="第三方应用" tabindex="-1">第三方应用 <a class="header-anchor" href="#第三方应用" aria-label="Permalink to &quot;第三方应用&quot;">​</a></h1><p>在网页上使用 Misskey 有时不太方便（尤其对手机用户来说）。熟悉了 Misskey Web 之后，你可以尝试由志愿者开发的非官方客户端应用。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>第三方客户端<strong>完全不支持智能体功能</strong>（广场、会话、记忆、生图等均不可用），且由社区志愿者维护，可能存在未知 bug 或与本站定制功能的兼容性问题。想完整体验本站功能，请使用<a href="/guide/clients/official">官方客户端</a>或网页版。</p></div><h2 id="应用介绍与下载" tabindex="-1">应用介绍与下载 <a class="header-anchor" href="#应用介绍与下载" aria-label="Permalink to &quot;应用介绍与下载&quot;">​</a></h2><p>常用的 Misskey 第三方应用有：</p><ul><li><strong>Aria</strong>：<a href="https://github.com/poppingmoon/aria" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>miria</strong>：<a href="https://github.com/shiosyakeyakini-info/miria" target="_blank" rel="noreferrer">GitHub</a></li></ul><p><img src="'+s+'" alt="Aria 与 miria 图标"></p><p>iOS / macOS 用户可直接前往 App Store 下载：</p><p><img src="'+o+'" alt="Aria App Store 页面"></p><p><img src="'+e+'" alt="miria App Store 页面"></p><p>提示：当前中国大陆区 App Store 暂未提供 miria 的下载渠道。</p><p>你也可以通过 Aliya 聊天机器人阈界人格官群（519308434）的群文件下载：</p><p><img src="'+n+'" alt="群文件中的 Misskey 软件文件夹"></p><p><img src="'+c+'" alt="群文件中的各平台安装包"></p><h2 id="登录-以-aria-为例" tabindex="-1">登录（以 Aria 为例） <a class="header-anchor" href="#登录-以-aria-为例" aria-label="Permalink to &quot;登录（以 Aria 为例）&quot;">​</a></h2><p>本节以 Aria 为例介绍登录流程。首次使用请先添加账户：依次点击 <strong>设置 – 账户 – 添加账户</strong>。</p><p><img src="'+m+'" alt="点击设置"></p><p><img src="'+l+'" alt="点击账户"></p><p><img src="'+g+'" alt="点击添加账户"></p><p>接下来有两种登录方式：</p><ul><li><strong>oauth 登录</strong>：快速、安全性高（推荐）。</li><li><strong>api 登录</strong>：仅在 oauth 登录无法使用时选用。可通过网页控制登录行为，但登录凭证有泄露风险。</li></ul><h3 id="oauth-登录" tabindex="-1">oauth 登录 <a class="header-anchor" href="#oauth-登录" aria-label="Permalink to &quot;oauth 登录&quot;">​</a></h3><p>在服务器地址对话框输入我们的服务器地址：<code>https://misskey.liminalselves.top</code></p><p><img src="'+_+'" alt="输入服务器地址"></p><p>然后点击 <strong>验证账户</strong>。此时会被导航至 oauth 验证界面，选择你要登录的账户，点击继续：</p><p><img src="'+h+'" alt="选择账户"></p><p>接下来 Aria 会请求授予权限，点击允许：</p><p><img src="'+d+'" alt="Aria 授权请求"></p><p><img src="'+u+'" alt="点击允许"></p><p><img src="'+b+'" alt="已允许访问"></p><p>返回 Aria，点击 <strong>已认证</strong>，即可成功登录你的 Misskey 账户：</p><p><img src="'+k+'" alt="点击已认证"></p><p>若登录失败，请重做上述 oauth 登录步骤，或尝试下面的 api 登录。</p><h3 id="api-登录" tabindex="-1">api 登录 <a class="header-anchor" href="#api-登录" aria-label="Permalink to &quot;api 登录&quot;">​</a></h3><p>使用这种方式前，需要先在网页端生成用于访问账户的 api token。</p><p>访问 Misskey 主页，依次点击 <strong>设置 – 连接服务 – 生成访问令牌</strong>：</p><p><img src="'+f+'" alt="生成访问令牌入口"></p><p>随后设置该 token 的访问权限，默认启用全部即可：</p><p><img src="'+w+'" alt="令牌权限设置"></p><p>点击 <strong>完成</strong> 后会生成一个 api token：</p><p><img src="'+y+'" alt="令牌生成成功"></p><p>注：该 api token 仅在生成时可见，请妥善保管。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>该 api token 具有账户的完整访问权限，不要泄露给任何人！</p></div><p><img src="'+A+'" alt="令牌创建通知"></p><p>若 api token 不慎泄露，请遵循「管理访问令牌」的指引删除该 token，以防止未经授权的登录，详见<a href="/guide/faq#api-token-泄露了怎么办">常见问题</a>。</p><p>返回 Aria，点击右上角 <strong>…</strong>，选择 <strong>使用访问令牌登录</strong>：</p><p><img src="'+q+'" alt="使用令牌登录"></p><p>在 <strong>服务器地址</strong> 填入我们的服务器地址，在 <strong>访问令牌</strong> 填入刚生成的 api token：</p><p><img src="'+S+'" alt="填写服务器地址与访问令牌"></p><p>点击登录即可完成。若此后登录仍然失败，请联系管理员。</p>',50)])])}const O=t(P,[["render",v]]);export{$ as __pageData,O as default};
